public static class __Judge
{
    const float Eps = 0.001f; // 각도 비교 허용 오차(도)

    static void Run(string id, System.Func<string> body)
    {
        string err;
        try { err = body(); }
        catch (System.Exception e) { err = "예외 발생: " + e.GetType().Name; }
        System.Console.WriteLine(err == null ? "[PASS] " + id : "[FAIL] " + id + " :: " + err);
    }

    static System.Numerics.Vector2 V(float x, float y) { return new System.Numerics.Vector2(x, y); }

    static string Turn(string what, System.Numerics.Vector2 pos, System.Numerics.Vector2 fwd, System.Numerics.Vector2 target, int expected)
    {
        int got = TurretMath.TurnDirection(pos, fwd, target);
        return got == expected ? null : what + ": 포탑 " + pos + ", forward " + fwd + ", 타깃 " + target + " → 기대 " + expected + " / 결과 " + got;
    }

    static string Angle(System.Numerics.Vector2 from, System.Numerics.Vector2 to, float expected, float eps)
    {
        float got = TurretMath.SignedAngleDegrees(from, to);
        return System.Math.Abs(got - expected) <= eps ? null : "SignedAngleDegrees(" + from + ", " + to + ") → 기대 " + expected + " / 결과 " + got;
    }

    public static void Main()
    {
        Run("cross-sign", () =>
        {
            float a = TurretMath.Cross(V(1f, 0f), V(0f, 1f));
            if (a != 1f) return "Cross((1,0),(0,1)) 기대 1 / 결과 " + a;
            float b = TurretMath.Cross(V(0f, 1f), V(1f, 0f));
            if (b != -1f) return "Cross((0,1),(1,0)) 기대 -1 / 결과 " + b;
            float c = TurretMath.Cross(V(2f, 3f), V(4f, 6f));
            if (c != 0f) return "평행한 벡터 Cross((2,3),(4,6)) 기대 0 / 결과 " + c;
            float d = TurretMath.Cross(V(3f, -2f), V(-5f, 4f));
            return d == 2f ? null : "Cross((3,-2),(-5,4)) 기대 2 / 결과 " + d;
        });

        Run("turn-left-right", () =>
            Turn("위를 보는 포탑, 왼쪽 앞 타깃", V(10f, 10f), V(0f, 1f), V(5f, 20f), 1)
            ?? Turn("위를 보는 포탑, 오른쪽 앞 타깃", V(10f, 10f), V(0f, 1f), V(15f, 20f), -1)
