using System;
using System.Numerics;

public static class FrameMath
{
    private static float Lerp(float a, float b, float t) => a + (b - a) * t;

    // 남은 차이 (target - current) 가 시간 dt 뒤에 exp(-sharpness * dt) 배가 되도록 한다.
    // exp(-k*a) * exp(-k*b) == exp(-k*(a+b)) 이므로 dt 를 어떻게 쪼개 호출해도 결과가 같다.
    public static float SmoothFollow(float current, float target, float sharpness, float dt)
    {
        if (!(sharpness > 0f) || !(dt > 0f)) return current; // 시간이 흐르지 않았으면 그대로
        float t = 1f - MathF.Exp(-sharpness * dt);            // 수학적으로 [0, 1). float 에서도 1 을 넘지 않는다
        return Lerp(current, target, t);
    }

    // 가속도가 dt 동안 일정하다고 보고 구간을 정확히 적분한다.
    //   p += v*dt + 0.5*a*dt^2   (이전 속도 기준)
    //   v += a*dt
    // 등가속도 운동에서는 프레임을 어떻게 나눠도 p0 + v0*T + 0.5*a*T^2 과 일치한다.
    public static void Integrate(ref Vector2 position, ref Vector2 velocity, Vector2 acceleration, float dt)
    {
        if (!(dt > 0f)) return;
        position += velocity * dt + acceleration * (0.5f * dt * dt);
        velocity += acceleration * dt;
    }
}

