    static float Follow(float start, float target, float k, int fps, float seconds)
    {
        float v = start;
        int frames = (int)System.Math.Round(fps * seconds);
        float dt = seconds / frames;
        for (int i = 0; i < frames; i++) v = FrameMath.SmoothFollow(v, target, k, dt);
        return v;
    }

    static void Simulate(ref System.Numerics.Vector2 p, ref System.Numerics.Vector2 v, System.Numerics.Vector2 a, int fps, float seconds)
    {
        int frames = (int)System.Math.Round(fps * seconds);
        float dt = seconds / frames;
        for (int i = 0; i < frames; i++) FrameMath.Integrate(ref p, ref v, a, dt);
    }

    static bool Near(float a, float b, float eps) { return System.Math.Abs(a - b) <= eps; }
    static bool Near(System.Numerics.Vector2 a, System.Numerics.Vector2 b, float eps) { return Near(a.X, b.X, eps) && Near(a.Y, b.Y, eps); }

