                double ox = System.Math.Max(System.Math.Max((double)a.Min.X - cx, (double)cx - a.Max.X), 0.0);
                double oy = System.Math.Max(System.Math.Max((double)a.Min.Y - cy, (double)cy - a.Max.Y), 0.0);
