using System;
using System.Numerics;

// 좌표 규약: 2D 평면, 단위는 미터. Vector2 는 "위치"와 "방향(변위)" 양쪽에 쓰인다.
public static class TargetingMath
{
    // 두 위치 사이 거리의 제곱. Sqrt 를 쓰지 않는다.
    public static float DistanceSquared(Vector2 a, Vector2 b)
    {
        float dx = b.X - a.X;
        float dy = b.Y - a.Y;
        return dx * dx + dy * dy;
    }

    // from 에서 to 를 향하는 길이 1 의 방향 벡터. 두 위치가 같으면 Vector2.Zero.
    public static Vector2 DirectionTo(Vector2 from, Vector2 to)
    {
        Vector2 offset = to - from;              // 위치 - 위치 = 변위(방향 + 거리)
        float lengthSq = offset.LengthSquared();
        if (lengthSq == 0f) return Vector2.Zero; // 0 으로 나누면 NaN 이 된다
        return offset / MathF.Sqrt(lengthSq);    // 방향이 실제로 필요한 곳에서만 Sqrt 한 번
    }

    // 사거리 maxRange(경계 포함) 안에서 가장 가까운 적의 인덱스. 없으면 -1. 동률이면 작은 인덱스.
    public static int FindNearestEnemy(Vector2 player, Vector2[] enemies, float maxRange)
    {
        float rangeSq = maxRange * maxRange;     // 비교 기준도 제곱해 둔다
        int best = -1;
        float bestSq = 0f;
        for (int i = 0; i < enemies.Length; i++)
        {
            float sq = DistanceSquared(player, enemies[i]);
            if (sq > rangeSq) continue;          // 사거리 밖 (경계는 포함)
            if (best == -1 || sq < bestSq)       // 엄격한 < : 동률이면 먼저 나온 적을 유지
            {
                best = i;
                bestSq = sq;
            }
        }
        return best;
    }
}

