using System;
using System.Numerics;

// 좌표 규약: +X 오른쪽, +Y 위쪽인 2D 평면.
public static class BounceMath
{
    // v 를 onto 방향 직선 위로 투영한 벡터: (v·onto / onto·onto) * onto
    public static Vector2 Project(Vector2 v, Vector2 onto)
    {
        float lengthSq = Vector2.Dot(onto, onto);
        if (lengthSq == 0f) return Vector2.Zero;       // 방향이 없으면 투영도 없다 (0/0 = NaN 방지)
        float scale = Vector2.Dot(v, onto) / lengthSq; // onto 를 정규화하지 않아도 되는 형태
        return onto * scale;
    }

    // v 에서 onto 방향 성분을 뺀 나머지. Project 와 더하면 항상 v 가 된다.
    public static Vector2 Reject(Vector2 v, Vector2 onto)
    {
        return v - Project(v, onto);
    }

    // 거울 반사: 법선 방향 성분만 부호를 뒤집는다. normal 은 단위 벡터라고 가정.
    public static Vector2 Reflect(Vector2 velocity, Vector2 normal)
    {
        float along = Vector2.Dot(velocity, normal);   // 법선 방향 성분의 크기(부호 포함)
        return velocity - 2f * along * normal;
    }
}

