using System;
using System.Numerics;

public static class SegmentMath
{
    // 선분 ab(양 끝점 포함) 위에서 p 에 가장 가까운 점.
    public static Vector2 ClosestPointOnSegment(Vector2 a, Vector2 b, Vector2 p)
    {
        Vector2 ab = b - a;
        float lengthSq = Vector2.Dot(ab, ab);
        if (lengthSq == 0f) return a;                  // 길이 0 인 선분: 0/0 방지

        // p 를 직선 a + t * ab 에 투영했을 때의 매개변수 t (t=0 이면 a, t=1 이면 b)
        float t = Vector2.Dot(p - a, ab) / lengthSq;
        t = Math.Clamp(t, 0f, 1f);                     // 직선이 아니라 선분이므로 [0, 1] 로 제한
        return a + ab * t;
    }

    // p 에서 선분 ab 까지 거리의 제곱.
    public static float DistanceSquaredToSegment(Vector2 a, Vector2 b, Vector2 p)
    {
        Vector2 offset = p - ClosestPointOnSegment(a, b, p);
        return Vector2.Dot(offset, offset);
    }

    // 선분 ab 가 원에 닿는가. 접하는 경우도 true (경계 포함).
    public static bool SegmentHitsCircle(Vector2 a, Vector2 b, Vector2 center, float radius)
    {
        return DistanceSquaredToSegment(a, b, center) <= radius * radius;
    }
}

