using System;
using System.Numerics;

public static class PlayerMovement
{
    // 입력(각 축 -1..1)을 길이 1 이하의 이동 방향으로 바꾼다.
    // 길이가 1 이하인 입력(아날로그 스틱)은 그대로 유지한다.
    public static Vector2 MoveDirection(Vector2 input)
    {
        // 수정 1: 축별 클램프는 사각형 안으로만 제한한다. (1,1) 의 길이는 1.414.
        // 길이(원) 기준으로 제한해야 대각선이 더 빨라지지 않는다.
        float lengthSq = input.LengthSquared();
        if (lengthSq > 1f)
        {
            return input / MathF.Sqrt(lengthSq);   // lengthSq > 1 이므로 0 으로 나눌 일이 없다
        }
        return input;                              // (0,0) 과 아날로그 입력은 그대로
    }

    // 이번 프레임의 이동 속도(단위/초). 속력은 최대 speed.
    public static Vector2 ComputeVelocity(Vector2 input, float speed)
    {
        // 수정 2: 속력을 곱한 뒤에 정규화하면 speed 가 지워진다.
        // 방향을 먼저 길이 1 이하로 만들고, 속력은 마지막에 한 번만 곱한다.
        return MoveDirection(input) * speed;
    }

    // 공격자에서 피격자 쪽으로 밀어내는 넉백 속도.
    // 두 위치가 같으면 Vector2.Zero.
    public static Vector2 KnockbackVelocity(Vector2 attackerPos, Vector2 victimPos, float force)
    {
        // 수정 3: 영벡터를 정규화하면 0/0 = NaN. 나누기 전에 길이를 검사한다.
        Vector2 offset = victimPos - attackerPos;
        float lengthSq = offset.LengthSquared();
        if (lengthSq < 1e-12f) return Vector2.Zero;
        return offset / MathF.Sqrt(lengthSq) * force;
    }
}

