public static class __Judge
{
    const float AngEps = 1e-3f; // 각도 허용 오차(도)
    const float VecEps = 1e-4f; // 벡터 성분 허용 오차

    static void Run(string id, System.Func<string> body)
    {
        string err;
        try { err = body(); }
        catch (System.Exception e) { err = "예외 발생: " + e.GetType().Name; }
        System.Console.WriteLine(err == null ? "[PASS] " + id : "[FAIL] " + id + " :: " + err);
    }

    static System.Numerics.Vector2 V(float x, float y) { return new System.Numerics.Vector2(x, y); }

    static string NearV(string what, System.Numerics.Vector2 got, float ex, float ey, float eps)
    {
        bool ok = System.Math.Abs(got.X - ex) <= eps && System.Math.Abs(got.Y - ey) <= eps; // NaN 이면 false
        return ok ? null : what + " → 기대 <" + ex + ", " + ey + "> / 결과 " + got;
    }
    static string Move(System.Numerics.Vector2 c, System.Numerics.Vector2 t, float step, float ex, float ey)
    { return NearV("MoveTowards(" + c + ", " + t + ", " + step + ")", SteeringMath.MoveTowards(c, t, step), ex, ey, VecEps); }
    static string MoveExact(System.Numerics.Vector2 c, System.Numerics.Vector2 t, float step, System.Numerics.Vector2 expected)
    {
        var got = SteeringMath.MoveTowards(c, t, step);
        return got == expected ? null : "MoveTowards(" + c + ", " + t + ", " + step + ") → 정확히 " + expected + " 이어야 함 / 결과 " + got;
    }
    static string Rot(System.Numerics.Vector2 c, System.Numerics.Vector2 t, float step, float ex, float ey)
    { return NearV("RotateTowards(" + c + ", " + t + ", " + step + ")", SteeringMath.RotateTowards(c, t, step), ex, ey, VecEps); }

    static string InRange(string what, float got)
    { return (got > -180f && got <= 180f) ? null : what + " → 범위 (-180, 180] 밖: " + got; }
    static string Ang(string what, float got, float expected)
    { return InRange(what, got) ?? (System.Math.Abs(got - expected) <= AngEps ? null : what + " → 기대 " + expected + " / 결과 " + got); }
    static string Wrap(float a, float expected) { return Ang("WrapAngle(" + a + ")", SteeringMath.WrapAngle(a), expected); }
    static string Delta(float f, float t, float expected) { return Ang("DeltaAngle(" + f + ", " + t + ")", SteeringMath.DeltaAngle(f, t), expected); }
    static string Step(float c, float t, float step, float expected) { return Ang("MoveTowardsAngle(" + c + ", " + t + ", " + step + ")", SteeringMath.MoveTowardsAngle(c, t, step), expected); }
    static string StepExact(float c, float t, float step, float expected)
    {
        float got = SteeringMath.MoveTowardsAngle(c, t, step);
        return got == expected ? null : "MoveTowardsAngle(" + c + ", " + t + ", " + step + ") → 정확히 " + expected + " 이어야 함 / 결과 " + got;
    }

    // 기준 구현(double): 부호 있는 최단 각도 차, 범위 (-180, 180]
    static double RefDelta(double from, double to)
    {
        double d = to - from;
        d -= 360.0 * System.Math.Floor((d + 180.0) / 360.0); // [-180, 180)
        return d == -180.0 ? 180.0 : d;
    }
    static double Mod360Diff(double a, double b) { double d = a - b; return System.Math.Abs(d - 360.0 * System.Math.Round(d / 360.0)); }

    public static void Main()
    {
