using System;
using System.Numerics;

public static class BlockPicker
{
    // 슬랩 방법: 상자를 "축마다 두 평면 사이의 구간(슬랩)" 세 개의 교집합으로 본다.
    // 축마다 반직선이 슬랩 안에 있는 t 구간 [t1, t2] 를 구하고, 세 구간과 [0, +inf) 의 교집합이
    // 비어 있지 않으면 명중이다. 교집합의 시작 tEnter 가 처음 닿는 지점의 매개변수다.
    public static bool RayAabb(Vector3 origin, Vector3 direction, Vector3 min, Vector3 max, out float distance)
    {
        distance = 0f;
        float lengthSq = direction.LengthSquared();
        if (lengthSq == 0f) return false;                 // 방향 없음

        float tEnter = 0f;                                // 0 에서 시작: 반직선의 뒤쪽(t < 0)을 잘라낸다
        float tExit = float.PositiveInfinity;

        if (!ClipToSlab(origin.X, direction.X, min.X, max.X, ref tEnter, ref tExit)) return false;
        if (!ClipToSlab(origin.Y, direction.Y, min.Y, max.Y, ref tEnter, ref tExit)) return false;
        if (!ClipToSlab(origin.Z, direction.Z, min.Z, max.Z, ref tEnter, ref tExit)) return false;

        distance = tEnter * MathF.Sqrt(lengthSq);         // 매개변수 t 를 월드 거리로: |direction| 배
        return true;
    }

    // 한 축의 슬랩 [lo, hi] 로 구간 [tEnter, tExit] 를 좁힌다. 구간이 비면 false.
    private static bool ClipToSlab(float o, float d, float lo, float hi, ref float tEnter, ref float tExit)
    {
        if (d == 0f)
        {
            // 이 축으로는 움직이지 않는다: 나눗셈 없이, 시작 좌표가 슬랩 안(경계 포함)인지만 본다.
            return o >= lo && o <= hi;
        }

        float inv = 1f / d;
        float t1 = (lo - o) * inv;
        float t2 = (hi - o) * inv;
        if (t1 > t2) { float tmp = t1; t1 = t2; t2 = tmp; }   // d < 0 이면 hi 쪽 평면을 먼저 만난다

        if (t1 > tEnter) tEnter = t1;                     // 가장 늦게 들어가는 시점
        if (t2 < tExit) tExit = t2;                       // 가장 일찍 나오는 시점
        return tEnter <= tExit;                           // 같으면 스치는 것: 명중으로 본다
    }
}

