public static class __Judge
{
    const float Eps = 0.001f; // 거리 비교 허용 오차

    static void Run(string id, System.Func<string> body)
    {
        string err;
        try { err = body(); }
        catch (System.Exception e) { err = "예외 발생: " + e.GetType().Name; }
        System.Console.WriteLine(err == null ? "[PASS] " + id : "[FAIL] " + id + " :: " + err);
    }

    static System.Numerics.Vector3 V(float x, float y, float z) { return new System.Numerics.Vector3(x, y, z); }

    static string Desc(System.Numerics.Vector3 o, System.Numerics.Vector3 d, System.Numerics.Vector3 mn, System.Numerics.Vector3 mx)
    {
        return "origin " + o + ", direction " + d + ", 상자 " + mn + " ~ " + mx;
    }

    static string Hit(string what, System.Numerics.Vector3 o, System.Numerics.Vector3 d, System.Numerics.Vector3 mn, System.Numerics.Vector3 mx, float expected, float eps)
    {
        float dist;
        bool hit = BlockPicker.RayAabb(o, d, mn, mx, out dist);
        if (!hit) return what + ": " + Desc(o, d, mn, mx) + " → 기대 명중(거리 " + expected + ") / 결과 빗나감";
        if (!(System.Math.Abs(dist - expected) <= eps)) return what + ": " + Desc(o, d, mn, mx) + " → 거리 기대 " + expected + " / 결과 " + dist;
        return null;
    }

    static string Miss(string what, System.Numerics.Vector3 o, System.Numerics.Vector3 d, System.Numerics.Vector3 mn, System.Numerics.Vector3 mx)
    {
        float dist;
        bool hit = BlockPicker.RayAabb(o, d, mn, mx, out dist);
        if (hit) return what + ": " + Desc(o, d, mn, mx) + " → 기대 빗나감 / 결과 명중(거리 " + dist + ")";
        if (dist != 0f) return what + ": 빗나갔을 때 distance 는 0 이어야 함 / 결과 " + dist;
        return null;
    }

    // 기준 구현(double): 여섯 면의 평면과 만나는 점을 하나씩 구해 그 점이 면 안에 있는지 확인한다.
    // 반환: 명중이면 거리(시작점이 상자 안이면 0), 아니면 -1. grow 만큼 상자를 키우거나(양수) 줄여서(음수) 검사한다.
    static double Reference(System.Numerics.Vector3 o, System.Numerics.Vector3 d, System.Numerics.Vector3 mn, System.Numerics.Vector3 mx, double grow)
    {
        double[] O = { o.X, o.Y, o.Z }, D = { d.X, d.Y, d.Z };
        double[] lo = { mn.X - grow, mn.Y - grow, mn.Z - grow }, hi = { mx.X + grow, mx.Y + grow, mx.Z + grow };
        bool inside = true;
        for (int k = 0; k < 3; k++) if (O[k] < lo[k] || O[k] > hi[k]) inside = false;
        if (inside) return 0;
        double len = System.Math.Sqrt(D[0] * D[0] + D[1] * D[1] + D[2] * D[2]);
        double best = double.PositiveInfinity;
        for (int axis = 0; axis < 3; axis++)
        {
            if (D[axis] == 0) continue;
            for (int side = 0; side < 2; side++)
            {
                double t = ((side == 0 ? lo[axis] : hi[axis]) - O[axis]) / D[axis];
                if (t < 0) continue;
                bool onFace = true;
                for (int k = 0; k < 3; k++)
                {
                    if (k == axis) continue;
                    double p = O[k] + t * D[k];
                    if (p < lo[k] || p > hi[k]) onFace = false;
                }
                if (onFace && t < best) best = t;
            }
        }
        return double.IsPositiveInfinity(best) ? -1 : best * len;
    }

