        });

        Run("random-vs-reference", () =>
        {
            var rng = new System.Random(20261122);
            int hits = 0, misses = 0, insides = 0;
            for (int i = 0; i < 4000; i++)
            {
                var c = V((float)(rng.NextDouble() * 20 - 10), (float)(rng.NextDouble() * 20 - 10), (float)(rng.NextDouble() * 20 - 10));
                var h = V((float)(0.5 + rng.NextDouble() * 4), (float)(0.5 + rng.NextDouble() * 4), (float)(0.5 + rng.NextDouble() * 4));
                var mn = c - h; var mx = c + h;
                var o = i % 7 == 0
                    ? c + V((float)(rng.NextDouble() * 2 - 1) * h.X, (float)(rng.NextDouble() * 2 - 1) * h.Y, (float)(rng.NextDouble() * 2 - 1) * h.Z)
                    : V((float)(rng.NextDouble() * 40 - 20), (float)(rng.NextDouble() * 40 - 20), (float)(rng.NextDouble() * 40 - 20));
                var aim = c + V((float)(rng.NextDouble() * 2 - 1) * h.X, (float)(rng.NextDouble() * 2 - 1) * h.Y, (float)(rng.NextDouble() * 2 - 1) * h.Z) * 1.6f;
                var d = i % 2 == 0 ? aim - o : V((float)(rng.NextDouble() * 2 - 1), (float)(rng.NextDouble() * 2 - 1), (float)(rng.NextDouble() * 2 - 1));
                if (i % 5 == 0) d.X = 0f;                 // 축과 나란한 방향을 섞는다
                if (i % 15 == 0) d.Z = 0f;
                if (d.Length() < 0.1f) continue;
                d *= (float)(0.05 + rng.NextDouble() * 4) / d.Length();
                // 경계에서 0.01 이내로 갈리는 입력(키운 상자와 줄인 상자의 판정이 다른 경우)은 판정하지 않는다
                double loose = Reference(o, d, mn, mx, 0.01), tight = Reference(o, d, mn, mx, -0.01), exact = Reference(o, d, mn, mx, 0.0);
                if ((loose < 0) != (tight < 0) || (loose == 0) != (tight == 0)) continue;
                string e;
                if (exact < 0) { misses++; e = Miss("무작위 #" + i, o, d, mn, mx); }
                else if (exact == 0) { insides++; e = Hit("무작위 #" + i + " (상자 안에서 출발)", o, d, mn, mx, 0f, Eps); }
                else { hits++; e = Hit("무작위 #" + i, o, d, mn, mx, (float)exact, 0.005f); }
                if (e != null) return e;
            }
            return hits > 800 && misses > 800 && insides > 200 ? null : "검사한 표본 수가 부족함: 명중 " + hits + " / 빗나감 " + misses + " / 안 " + insides;
        });
    }
}

