using System;
using System.Numerics;

public enum SegmentHit
{
    None,     // 공통점 없음
    Point,    // 공통점이 정확히 한 점
    Overlap   // 일직선 위에서 길이가 있는 구간이 겹침
}

public static class LaserMath
{
    // 2D 외적(스칼라): 0 이면 두 벡터가 평행.
    private static float Cross(Vector2 u, Vector2 v) { return u.X * v.Y - u.Y * v.X; }

    // 선분을 매개변수로 쓴다: P(t) = a + t*r (0 <= t <= 1), Q(u) = c + u*s (0 <= u <= 1).
    // a + t*r = c + u*s 의 양변에 s (또는 r) 와의 외적을 취하면
    //   t = Cross(c - a, s) / Cross(r, s),   u = Cross(c - a, r) / Cross(r, s)
    public static SegmentHit Intersect(Vector2 a, Vector2 b, Vector2 c, Vector2 d, out Vector2 point)
    {
        point = Vector2.Zero;
        Vector2 r = b - a;
        Vector2 s = d - c;
        Vector2 ac = c - a;
        float rr = Vector2.Dot(r, r);
        float ss = Vector2.Dot(s, s);

        // 1) 길이가 0 인 선분은 점으로 취급한다.
        if (rr == 0f && ss == 0f)
        {
            if (a != c) return SegmentHit.None;
            point = a;
            return SegmentHit.Point;
        }
        if (rr == 0f)
        {
            if (!PointOnSegment(a, c, s, ss)) return SegmentHit.None;
            point = a;
            return SegmentHit.Point;
        }
        if (ss == 0f)
        {
            if (!PointOnSegment(c, a, r, rr)) return SegmentHit.None;
            point = c;
            return SegmentHit.Point;
        }

        float denom = Cross(r, s);
        if (denom != 0f)
        {
            // 2) 평행하지 않다: 두 직선은 한 점에서 만난다. 그 점이 두 선분 안에 있는지만 본다.
            //    0 <= t <= 1 을 나눗셈 없이 검사한다: 분모가 음수면 분자·분모의 부호를 함께 뒤집는다.
            float tNum = Cross(ac, s);
            float uNum = Cross(ac, r);
            if (denom < 0f) { tNum = -tNum; uNum = -uNum; denom = -denom; }
            if (tNum < 0f || tNum > denom || uNum < 0f || uNum > denom) return SegmentHit.None;
            point = a + r * (tNum / denom);
            return SegmentHit.Point;
        }

        // 3) 평행하다. c 가 직선 ab 위에 없으면 서로 다른 평행선이다.
        if (Cross(ac, r) != 0f) return SegmentHit.None;

        // 4) 일직선: c, d 를 a-b 축에 투영한다. 값 e 는 "t * rr" 이므로 a-b 구간은 [0, rr] 이다.
        float e0 = Vector2.Dot(ac, r);
        float e1 = Vector2.Dot(d - a, r);
        float lo = MathF.Min(e0, e1);
        float hi = MathF.Max(e0, e1);
        if (lo < 0f) lo = 0f;
        if (hi > rr) hi = rr;
        if (lo > hi) return SegmentHit.None;              // 일직선이지만 떨어져 있다

        point = a + r * (lo / rr);                        // 겹친 구간에서 a 에 가장 가까운 점
        return lo == hi ? SegmentHit.Point : SegmentHit.Overlap;
    }

    // 점 p 가 선분 q + u*s (0 <= u <= 1, ss = s.s > 0) 위에 있는가.
    private static bool PointOnSegment(Vector2 p, Vector2 q, Vector2 s, float ss)
    {
        Vector2 qp = p - q;
        if (Cross(qp, s) != 0f) return false;             // 직선 위에 없다
        float e = Vector2.Dot(qp, s);
        return e >= 0f && e <= ss;
    }
}

