public static class __Judge
{
    const float Eps = 0.0001f; // 교점 좌표 허용 오차(성분별)

    static void Run(string id, System.Func<string> body)
    {
        string err;
        try { err = body(); }
        catch (System.Exception e) { err = "예외 발생: " + e.GetType().Name; }
        System.Console.WriteLine(err == null ? "[PASS] " + id : "[FAIL] " + id + " :: " + err);
    }

    static System.Numerics.Vector2 V(float x, float y) { return new System.Numerics.Vector2(x, y); }

    static string Check(string what, System.Numerics.Vector2 a, System.Numerics.Vector2 b, System.Numerics.Vector2 c, System.Numerics.Vector2 d, SegmentHit kind, System.Numerics.Vector2 expected)
    {
        System.Numerics.Vector2 p;
        SegmentHit got = LaserMath.Intersect(a, b, c, d, out p);
        string desc = what + ": " + a + "-" + b + " vs " + c + "-" + d;
        if (got != kind) return desc + " → 기대 " + kind + " / 결과 " + got;
        if (!(System.Math.Abs(p.X - expected.X) <= Eps && System.Math.Abs(p.Y - expected.Y) <= Eps))
            return desc + " → " + kind + " 의 point 기대 " + expected + " / 결과 " + p;
        return null;
    }

    static string Pt(string what, float ax, float ay, float bx, float by, float cx, float cy, float dx, float dy, float px, float py)
    { return Check(what, V(ax, ay), V(bx, by), V(cx, cy), V(dx, dy), SegmentHit.Point, V(px, py)); }

    static string Ov(string what, float ax, float ay, float bx, float by, float cx, float cy, float dx, float dy, float px, float py)
    { return Check(what, V(ax, ay), V(bx, by), V(cx, cy), V(dx, dy), SegmentHit.Overlap, V(px, py)); }

    static string No(string what, float ax, float ay, float bx, float by, float cx, float cy, float dx, float dy)
    { return Check(what, V(ax, ay), V(bx, by), V(cx, cy), V(dx, dy), SegmentHit.None, V(0f, 0f)); }

    static long Orient(long ax, long ay, long bx, long by, long cx, long cy) { return (bx - ax) * (cy - ay) - (by - ay) * (cx - ax); }

    // 기준 구현: 정수 좌표를 long 으로 계산하는 방향(orientation) 판정 + 직선의 일반형(Ax + By = C) 연립.
    static SegmentHit Reference(long[] q, out double px, out double py)
    {
        px = 0; py = 0;
        long o1 = Orient(q[0], q[1], q[2], q[3], q[4], q[5]), o2 = Orient(q[0], q[1], q[2], q[3], q[6], q[7]);
        long o3 = Orient(q[4], q[5], q[6], q[7], q[0], q[1]), o4 = Orient(q[4], q[5], q[6], q[7], q[2], q[3]);
        if (o1 == 0 && o2 == 0 && o3 == 0 && o4 == 0)
        {
            // 네 점이 일직선: 좌표가 변하는 축 하나로 1차원 구간 겹침을 본다
            int k = (q[0] != q[2] || q[4] != q[6] || q[0] != q[4]) ? 0 : 1;
            long ka = q[k], kb = q[2 + k], kc = q[4 + k], kd = q[6 + k];
            long lo = System.Math.Max(System.Math.Min(ka, kb), System.Math.Min(kc, kd));
            long hi = System.Math.Min(System.Math.Max(ka, kb), System.Math.Max(kc, kd));
            if (lo > hi) return SegmentHit.None;
            long want = System.Math.Min(System.Math.Max(ka, lo), hi); // 겹친 구간에서 a 에 가장 가까운 위치
            for (int i = 0; i < 8; i += 2) if (q[i + k] == want) { px = q[i]; py = q[i + 1]; break; }
            return lo == hi ? SegmentHit.Point : SegmentHit.Overlap;
        }
        bool straddle1 = (o1 <= 0 && o2 >= 0) || (o1 >= 0 && o2 <= 0);
        bool straddle2 = (o3 <= 0 && o4 >= 0) || (o3 >= 0 && o4 <= 0);
        if (!straddle1 || !straddle2) return SegmentHit.None;
        double A1 = q[3] - q[1], B1 = q[0] - q[2], C1 = A1 * q[0] + B1 * q[1];
        double A2 = q[7] - q[5], B2 = q[4] - q[6], C2 = A2 * q[4] + B2 * q[5];
        double det = A1 * B2 - A2 * B1;
        if (det == 0) return SegmentHit.None; // 한쪽이 점이고 상대 직선 위에 없는 경우
        px = (B2 * C1 - B1 * C2) / det; py = (A1 * C2 - A2 * C1) / det;
        return SegmentHit.Point;
    }

    public static void Main()
