            ?? No("아슬아슬하게 닿지 않음", 0, 0, 4, 0, 2, 0.25f, 2, 3)
            ?? No("수평 평행선", 0, 0, 4, 0, 0, 1, 4, 1)
            ?? No("대각 평행선", 0, 0, 2, 2, 1, 0, 3, 2));

        Run("endpoint-touch", () =>
