            ?? Pt("V 자: a 와 c 가 같은 점", 0, 0, 3, 1, 0, 0, -2, 5, 0, 0)
            ?? Pt("b 가 c-d 의 중간에 놓임", 1, 1, 3, 3, 0, 6, 6, 0, 3, 3)
