        Run("zero-length-segment", () =>
            Pt("a == b 가 c-d 위", 2, 0, 2, 0, 0, 0, 4, 0, 2, 0)
            ?? Pt("a == b 가 c-d 의 끝점", 4, 0, 4, 0, 0, 0, 4, 0, 4, 0)
            ?? No("a == b 가 c-d 밖(직선에서 벗어남)", 2, 1, 2, 1, 0, 0, 4, 0)
            ?? No("a == b 가 c-d 의 연장선 위", 5, 0, 5, 0, 0, 0, 4, 0)
