            ?? No("서로 다른 두 점", 3, -2, 3, -2, 3, 5, 3, 5));

        Run("random-vs-reference", () =>
        {
            var rng = new System.Random(20261122);
            int[] seen = new int[3];
            for (int i = 0; i < 6000; i++)
            {
                long[] q = new long[8];
                if (i % 3 == 0)
                {
                    // 일직선 위의 네 점: 기준점 + 정수배
                    long bx = rng.Next(-4, 5), by = rng.Next(-4, 5), vx = rng.Next(-2, 3), vy = rng.Next(-2, 3);
                    for (int k = 0; k < 8; k += 2) { long m = rng.Next(-4, 5); q[k] = bx + m * vx; q[k + 1] = by + m * vy; }
                }
                else
                {
                    for (int k = 0; k < 8; k++) q[k] = rng.Next(-5, 6);
                    if (i % 10 == 1) { q[2] = q[0]; q[3] = q[1]; }   // 길이 0 인 a-b
