using System;
using System.Numerics;

// 각도 규약: +X 방향이 0도, 반시계 방향(+X 에서 +Y 쪽)이 양수. 공개 함수의 각도는 모두 "도" 단위.
public static class TurretAim
{
    // from 에서 to 를 바라보는 각도(도). 범위 (-180, 180]. 두 위치가 같으면 0.
    public static float AngleTo(Vector2 from, Vector2 to)
    {
        Vector2 offset = to - from;
        if (offset == Vector2.Zero) return 0f;
        return MathF.Atan2(offset.X, offset.Y) * (180f / MathF.PI);
    }

    // 각도(도)가 가리키는 길이 1 의 방향 벡터.
    public static Vector2 DirectionFromAngle(float degrees)
    {
        return new Vector2(MathF.Cos(degrees), MathF.Sin(degrees));
    }

    // fromDegrees 에서 toDegrees 로 "가까운 쪽으로" 도는 보간. t 는 [0, 1] 로 제한한다.
    // 반환값은 fromDegrees + (가장 짧은 각도 차이) * t 이며 0~360 으로 정규화하지 않는다.
    public static float LerpAngle(float fromDegrees, float toDegrees, float t)
    {
        t = Math.Clamp(t, 0f, 1f);
        return fromDegrees + (toDegrees - fromDegrees) * t;
    }
}

