public static class __Judge
{
    static void Run(string id, System.Func<string> body)
    {
        string err;
        try { err = body(); }
        catch (System.Exception e) { err = "예외 발생: " + e.GetType().Name; }
        System.Console.WriteLine(err == null ? "[PASS] " + id : "[FAIL] " + id + " :: " + err);
    }

    static System.Numerics.Vector2 V(float x, float y) { return new System.Numerics.Vector2(x, y); }

    // 두 각도(도)의 차이를 360 의 배수를 무시하고 0~180 으로 잰다.
    static double AngDiff(double a, double b)
    {
        double d = (a - b) % 360.0;
        if (d < 0) d += 360.0;
        return d > 180.0 ? 360.0 - d : d;
    }

    static string Ang(string what, float fx, float fy, float tx, float ty, float expected)
    {
        float got = TurretAim.AngleTo(V(fx, fy), V(tx, ty));
        string desc = what + ": AngleTo((" + fx + ", " + fy + "), (" + tx + ", " + ty + "))";
        if (float.IsNaN(got) || AngDiff(got, expected) > 0.01) return desc + " → 기대 " + expected + "도 / 결과 " + got;
        if (got <= -180.01f || got > 180.01f) return desc + " → 범위 (-180, 180] 를 벗어남: " + got;
        return null;
    }

    static string Dir(float degrees, float ex, float ey)
    {
        var got = TurretAim.DirectionFromAngle(degrees);
        if (System.Math.Abs(got.X - ex) <= 0.0001f && System.Math.Abs(got.Y - ey) <= 0.0001f) return null;
        return "DirectionFromAngle(" + degrees + ") → 기대 (" + ex + ", " + ey + ") / 결과 " + got;
    }

    static string Lerp(string what, float from, float to, float t, float expected)
    {
        float got = TurretAim.LerpAngle(from, to, t);
        if (!float.IsNaN(got) && AngDiff(got, expected) <= 0.01) return null;
        return what + ": LerpAngle(" + from + ", " + to + ", " + t + ") → 기대 " + expected + "도(360 의 배수 차이는 같은 각도) / 결과 " + got;
    }

    public static void Main()
    {
        Run("angle-cardinals", () =>
            Ang("오른쪽", 0, 0, 5, 0, 0f)
            ?? Ang("위", 0, 0, 0, 5, 90f)
            ?? Ang("왼쪽", 0, 0, -5, 0, 180f)
            ?? Ang("아래", 0, 0, 0, -5, -90f)
            ?? Ang("원점이 아닌 포탑에서 위", 2, 3, 2, 8, 90f)
            ?? Ang("같은 위치는 0", 4, -2, 4, -2, 0f));

        Run("angle-quadrants", () =>
            Ang("1사분면 45도", 0, 0, 1, 1, 45f)
            ?? Ang("1사분면 30도", 0, 0, 1.7320508f, 1, 30f)
            ?? Ang("1사분면 60도", 0, 0, 1, 1.7320508f, 60f)
            ?? Ang("2사분면", 0, 0, -1, 1, 135f)
            ?? Ang("3사분면", 0, 0, -1, -1, -135f)
            ?? Ang("4사분면", 0, 0, 1, -1, -45f)
            ?? Ang("원점이 아닌 포탑", 10, -4, 7, -1, 135f));

        Run("direction-from-degrees", () =>
            Dir(0f, 1f, 0f) ?? Dir(90f, 0f, 1f) ?? Dir(180f, -1f, 0f) ?? Dir(270f, 0f, -1f)
            ?? Dir(-90f, 0f, -1f) ?? Dir(60f, 0.5f, 0.8660254f) ?? Dir(360f, 1f, 0f) ?? Dir(-135f, -0.70710678f, -0.70710678f));

        Run("angle-direction-roundtrip", () =>
        {
            for (int a = -170; a <= 180; a += 10)
            {
                var from = V(3f, -2f);
                var to = from + TurretAim.DirectionFromAngle(a) * 7f;
                float back = TurretAim.AngleTo(from, to);
                if (float.IsNaN(back) || AngDiff(back, a) > 0.01) return a + "도 방향으로 7 만큼 떨어진 목표를 다시 AngleTo 로 재면 " + a + "도여야 함 / 결과 " + back;
            }
            return null;
        });

        Run("lerp-without-seam", () =>
            Lerp("경계를 넘지 않는 보간", 10f, 50f, 0.25f, 20f)
            ?? Lerp("감소 방향", 50f, 10f, 0.5f, 30f)
            ?? Lerp("180도를 사이에 둔 보간", 200f, 300f, 0.5f, 250f)
            ?? Lerp("t = 0 은 시작 각도", 80f, 200f, 0f, 80f)
            ?? Lerp("t = 1 은 목표 각도", 80f, 200f, 1f, 200f));

        Run("lerp-across-seam", () =>
            Lerp("350 → 10 의 중간은 0도(180도가 아님)", 350f, 10f, 0.5f, 0f)
            ?? Lerp("350 → 10 의 1/4", 350f, 10f, 0.25f, 355f)
            ?? Lerp("10 → 350 의 1/4", 10f, 350f, 0.25f, 5f)
            ?? Lerp("300 → 20 은 0도를 지나는 쪽이 가깝다", 300f, 20f, 0.5f, 340f)
            ?? Lerp("5 → 355 의 중간", 5f, 355f, 0.5f, 0f)
            ?? Lerp("0 → 270 은 -90도 쪽이 가깝다", 0f, 270f, 0.5f, -45f)
            ?? Lerp("359 → 0", 359f, 0f, 0.5f, 359.5f)
            ?? Lerp("t = 1 은 목표와 같은 각도", 350f, 10f, 1f, 10f));

        Run("lerp-clamps-t", () =>
            Lerp("t < 0 은 0 으로", 20f, 100f, -1f, 20f)
            ?? Lerp("t > 1 은 1 로", 20f, 100f, 2f, 100f)
            ?? Lerp("경계를 넘는 보간에서 t > 1", 350f, 10f, 5f, 10f));

        Run("random-lerp-vs-reference", () =>
        {
            var rng = new System.Random(20261122);
            for (int i = 0; i < 3000; i++)
            {
                // 가장 짧은 차이 delta 를 먼저 정하고(정확히 반 바퀴 근처는 제외) 목표를 [0, 360) 으로 감는다
                float from = (float)(rng.NextDouble() * 359.9);
                float delta = (float)(rng.NextDouble() * 358 - 179);
                float to = from + delta;
                if (to < 0f) to += 360f; else if (to >= 360f) to -= 360f;
                if (!(to >= 0f && to < 360f)) continue;
                float t = (float)rng.NextDouble();
                string e = Lerp("무작위 #" + i, from, to, t, (float)((double)from + (double)delta * t));
                if (e != null) return e;
            }
            return null;
        });
    }
}

