problems.solutionCode:
using System;
using System.Numerics;

public static class Interp
{
    // a 에서 b 로 t 만큼 선형 보간. t 를 제한하지 않는다(범위를 벗어나면 외삽).
    public static float Lerp(float a, float b, float t)
    {
        return a + (b - a) * t;
    }

    // Lerp 의 역: value 가 a~b 구간의 어디쯤인지(0~1 비율). 제한하지 않는다. a == b 이면 0.
    public static float InverseLerp(float a, float b, float value)
    {
        if (a == b) return 0f;                  // 구간의 길이가 0: 0 으로 나누지 않는다
        return (value - a) / (b - a);
    }

    // value 를 [inMin, inMax] 에서 [outMin, outMax] 로 옮긴다. 비율은 [0, 1] 로 제한한다.
    public static float Remap(float inMin, float inMax, float outMin, float outMax, float value)
    {
        float t = Math.Clamp(InverseLerp(inMin, inMax, value), 0f, 1f);
        return Lerp(outMin, outMax, t);
    }

    // t 를 [0, 1] 로 제한한 뒤 3t^2 - 2t^3. 양 끝에서 기울기가 0 이다.
    public static float SmoothStep01(float t)
    {
        t = Math.Clamp(t, 0f, 1f);
        return t * t * (3f - 2f * t);
    }

    // 체력바 색 그라디언트의 매개변수(0 = 빨강, 1 = 초록).
    // 체력 비율이 20% 이하면 0, 60% 이상이면 1, 그 사이는 SmoothStep01 로 부드럽게.
    // maxHealth <= 0 이면 0.
    public static float HealthGradientT(float health, float maxHealth)
    {
        if (!(maxHealth > 0f)) return 0f;
        float ratio = health / maxHealth;                       // 값 -> 비율
        return SmoothStep01(InverseLerp(0.2f, 0.6f, ratio));    // 비율 -> 구간 안의 위치 -> 곡선
    }

    // 체력바 색(RGB, 각 성분 0~1). 빨강 (1, 0, 0) 에서 초록 (0, 1, 0) 으로 HealthGradientT 만큼 보간.
    public static Vector3 HealthColor(float health, float maxHealth)
    {
        float t = HealthGradientT(health, maxHealth);
        return new Vector3(Lerp(1f, 0f, t), Lerp(0f, 1f, t), 0f);
    }
}

