public static class Ballistics
{
    // 발사 속력 speed 가 고정일 때, origin 에서 쏜 포탄이 target 을 지나도록 하는 발사 속도 벡터를 구한다.
    //   - 중력은 -Y 방향으로 gravity (양수, 단위/초^2) 만큼 작용한다. 공기 저항은 없다.
    //     위치(t) = origin + velocity * t + (0, -gravity, 0) * t * t / 2
    //   - 해가 두 개면 highArc = false 일 때 낮은 탄도(발사각이 작은 쪽, 먼저 도착),
    //     highArc = true 일 때 높은 탄도(발사각이 큰 쪽)를 반환한다. 해가 하나면 둘 다 그 해.
    //   - 닿을 수 없으면 false, velocity = Vector3.Zero.
    //   - speed <= 0, gravity <= 0, 또는 수평 거리(XZ 평면)가 0 이면 false, velocity = Vector3.Zero.
    //   - true 일 때 velocity 의 길이는 speed 이고, 수평 성분은 target 쪽을 향한다.
    public static bool SolveLaunchVelocity(Vector3 origin, Vector3 target, float speed, float gravity, bool highArc, out Vector3 velocity)
    {
