using System;
using System.Numerics;

public static class Ballistics
{
    // 수평 거리 x, 높이 차 y, 속력 v, 중력 g 일 때 발사각 theta 는
    //   tan(theta) = (v^2 ± sqrt(v^4 - g (g x^2 + 2 y v^2))) / (g x)
    // 를 만족한다. 루트 안이 음수면 그 속력으로는 닿지 않는다. - 가 낮은 탄도, + 가 높은 탄도.
    public static bool SolveLaunchVelocity(Vector3 origin, Vector3 target, float speed, float gravity, bool highArc, out Vector3 velocity)
    {
        velocity = Vector3.Zero;
        if (!(speed > 0f) || !(gravity > 0f)) return false;

        Vector3 offset = target - origin;
        float x = MathF.Sqrt(offset.X * offset.X + offset.Z * offset.Z);   // 수평 거리
        float y = offset.Y;                                                // 높이 차 (+ 가 위)
        if (x == 0f) return false;                                         // 수평 방향을 정할 수 없다

        float v2 = speed * speed;
        float disc = v2 * v2 - gravity * (gravity * x * x + 2f * y * v2);
        if (disc < 0f) return false;                                       // 사거리 밖

        float root = MathF.Sqrt(disc);
        float tan = (highArc ? v2 + root : v2 - root) / (gravity * x);

        // tan 에서 cos, sin 을 직접 만든다(각도로 바꿨다가 되돌리지 않는다). -90도 < theta < 90도 이므로 cos > 0.
        float cos = 1f / MathF.Sqrt(1f + tan * tan);
        float sin = tan * cos;

        float horizontalSpeed = speed * cos;
        velocity = new Vector3(offset.X / x * horizontalSpeed, speed * sin, offset.Z / x * horizontalSpeed);
        return true;
    }
}

