{{USER_CODE}}

public static class __Judge
{
    static void Run(string id, System.Func<string> body)
    {
        string err;
        try { err = body(); }
        catch (System.Exception e) { err = "예외 발생: " + e.GetType().Name; }
        System.Console.WriteLine(err == null ? "[PASS] " + id : "[FAIL] " + id + " :: " + err);
    }

    static System.Numerics.Vector3 V(float x, float y, float z) { return new System.Numerics.Vector3(x, y, z); }

    static string Desc(System.Numerics.Vector3 o, System.Numerics.Vector3 t, float v, float g, bool high)
    {
        return "origin " + o + ", target " + t + ", speed " + v + ", gravity " + g + (high ? ", 높은 탄도" : ", 낮은 탄도");
    }

    // 반환된 속도로 실제로 날려 본다(double): 속력이 speed 인지, 수평으로 target 에 도달한 순간의 위치가 target 인지.
    // 통과하면 null 을 반환하고 flightTime 에 비행 시간을 담는다.
    static string Fly(string what, System.Numerics.Vector3 o, System.Numerics.Vector3 t, float v, float g, bool high, out System.Numerics.Vector3 vel, out double flightTime)
    {
        flightTime = 0;
        bool ok = Ballistics.SolveLaunchVelocity(o, t, v, g, high, out vel);
        string desc = what + ": " + Desc(o, t, v, g, high);
        if (!ok) return desc + " → 기대 true / 결과 false";
        double vx = vel.X, vy = vel.Y, vz = vel.Z;
        double len = System.Math.Sqrt(vx * vx + vy * vy + vz * vz);
        if (!(System.Math.Abs(len - v) <= 0.005)) return desc + " → 속도의 길이 기대 " + v + " / 결과 " + len.ToString("F4") + " (velocity " + vel + ")";
        double dx = (double)t.X - o.X, dy = (double)t.Y - o.Y, dz = (double)t.Z - o.Z;
        double hh = vx * vx + vz * vz;
        if (!(hh > 1e-12)) return desc + " → 수평 속도가 0 (velocity " + vel + ")";
        double time = (dx * vx + dz * vz) / hh;
        if (!(time > 0)) return desc + " → 수평 속도가 target 반대쪽을 향함 (velocity " + vel + ")";
        double px = vx * time, py = vy * time - 0.5 * g * time * time, pz = vz * time;
        if (!(System.Math.Abs(px - dx) <= 0.02 && System.Math.Abs(py - dy) <= 0.02 && System.Math.Abs(pz - dz) <= 0.02))
            return desc + " → velocity " + vel + " 로 쏘면 " + time.ToString("F3") + "초 뒤 origin 기준 (" + px.ToString("F3") + ", " + py.ToString("F3") + ", " + pz.ToString("F3") + ") 에 있음 / target 은 (" + dx + ", " + dy + ", " + dz + ")";
        flightTime = time;
        return null;
    }

    static string Expect(string what, System.Numerics.Vector3 o, System.Numerics.Vector3 t, float v, float g, bool high, float ex, float ey, float ez)
    {
        System.Numerics.Vector3 vel; double time;
        string e = Fly(what, o, t, v, g, high, out vel, out time);
        if (e != null) return e;
        if (System.Math.Abs(vel.X - ex) <= 0.002f && System.Math.Abs(vel.Y - ey) <= 0.002f && System.Math.Abs(vel.Z - ez) <= 0.002f) return null;
        return what + ": " + Desc(o, t, v, g, high) + " → velocity 기대 (" + ex + ", " + ey + ", " + ez + ") / 결과 " + vel + " (두 탄도를 바꿔 반환했는지 확인)";
    }

    // 두 탄도가 모두 명중하고, 낮은 탄도가 발사각이 작으며 먼저 도착하는지 확인한다.
    static string Both(string what, System.Numerics.Vector3 o, System.Numerics.Vector3 t, float v, float g)
    {
        System.Numerics.Vector3 lowV, highV; double lowT, highT;
        string e = Fly(what, o, t, v, g, false, out lowV, out lowT) ?? Fly(what, o, t, v, g, true, out highV, out highT);
        if (e != null) return e;
        Ballistics.SolveLaunchVelocity(o, t, v, g, true, out highV);
        if (!(lowV.Y < highV.Y - 0.01f)) return what + ": origin " + o + ", target " + t + ", speed " + v + ", gravity " + g + " → 낮은 탄도의 velocity.Y(" + lowV.Y + ")가 높은 탄도(" + highV.Y + ")보다 작아야 함";
        return null;
    }

    static string Fail(string what, System.Numerics.Vector3 o, System.Numerics.Vector3 t, float v, float g)
    {
        for (int k = 0; k < 2; k++)
        {
            System.Numerics.Vector3 vel;
            bool ok = Ballistics.SolveLaunchVelocity(o, t, v, g, k == 1, out vel);
            if (ok) return what + ": " + Desc(o, t, v, g, k == 1) + " → 기대 false / 결과 true (velocity " + vel + ")";
            if (!(vel.X == 0f && vel.Y == 0f && vel.Z == 0f)) return what + ": false 일 때 velocity 는 Vector3.Zero 여야 함 / 결과 " + vel;
        }
        return null;
    }

    public static void Main()
    {
        var O = V(0f, 0f, 0f);

        Run("flat-two-arcs", () =>
            Expect("평지 20, 속력 20, 중력 10: 낮은 탄도는 15도", O, V(20f, 0f, 0f), 20f, 10f, false, 19.318517f, 5.176381f, 0f)
            ?? Expect("같은 조건의 높은 탄도는 75도", O, V(20f, 0f, 0f), 20f, 10f, true, 5.176381f, 19.318517f, 0f)
            ?? Expect("-X 쪽 목표", O, V(-20f, 0f, 0f), 20f, 10f, false, -19.318517f, 5.176381f, 0f));

        Run("elevated-target-3d", () =>
            Expect("수평 20, 위로 10: 낮은 탄도 tan = 1", V(1f, 2f, 3f), V(13f, 12f, 19f), 20f, 10f, false, 8.485281f, 14.142136f, 11.313708f)
            ?? Expect("수평 20, 위로 10: 높은 탄도 tan = 3", V(1f, 2f, 3f), V(13f, 12f, 19f), 20f, 10f, true, 3.794733f, 18.973666f, 5.059644f));

        Run("target-below", () =>
            Expect("절벽 위에서 아래로: 낮은 탄도는 아래를 향해 쏜다", V(0f, 10f, 0f), V(0f, 0f, 20f), 20f, 10f, false, 0f, -4.595058f, 19.46498f)
            ?? Expect("절벽 위에서 아래로: 높은 탄도", V(0f, 10f, 0f), V(0f, 0f, 20f), 20f, 10f, true, 0f, 19.46498f, 4.595058f)
            ?? Both("더 깊은 낙차", V(5f, 40f, -5f), V(-25f, 0f, 35f), 18f, 9.81f));

        Run("out-of-range", () =>
            Fail("평지 최대 사거리 10 인데 목표는 20", O, V(20f, 0f, 0f), 10f, 10f)
            ?? Fail("평지 최대 사거리 40 을 조금 넘음", O, V(41f, 0f, 0f), 20f, 10f)
            ?? Fail("너무 높은 목표", O, V(5f, 30f, 0f), 20f, 10f)
            ?? Both("최대 사거리 안쪽(39)은 닿는다", O, V(39f, 0f, 0f), 20f, 10f));

        Run("invalid-input", () =>
            Fail("speed 0", O, V(20f, 0f, 0f), 0f, 10f)
            ?? Fail("speed 음수", O, V(20f, 0f, 0f), -20f, 10f)
            ?? Fail("gravity 0", O, V(20f, 0f, 0f), 20f, 0f)
            ?? Fail("gravity 음수", O, V(20f, 0f, 0f), 20f, -10f)
            ?? Fail("origin 과 target 이 같음", V(3f, 4f, 5f), V(3f, 4f, 5f), 20f, 10f)
            ?? Fail("바로 위(수평 거리 0)", O, V(0f, 5f, 0f), 20f, 10f)
            ?? Fail("바로 아래(수평 거리 0)", O, V(0f, -5f, 0f), 20f, 10f));

        Run("gravity-and-direction", () =>
            Both("중력 9.81, 대각선 방향", O, V(30f, 4f, -40f), 25f, 9.81f)
            ?? Both("중력이 약한 달 맵", V(-3f, 1f, 2f), V(40f, -6f, 60f), 12f, 1.62f)
            ?? Both("가까운 목표", V(2f, 0f, 2f), V(4f, 1f, 1f), 15f, 9.81f));

        Run("random-simulation", () =>
        {
            var rng = new System.Random(20261122);
            int reach = 0, unreachable = 0;
            for (int i = 0; i < 3000; i++)
            {
                float v = (float)(10 + rng.NextDouble() * 30), g = (float)(5 + rng.NextDouble() * 15);
                var o = V((float)(rng.NextDouble() * 20 - 10), (float)(rng.NextDouble() * 20 - 10), (float)(rng.NextDouble() * 20 - 10));
                double ang = rng.NextDouble() * 2 * System.Math.PI, dist = 3 + rng.NextDouble() * 80;
                var t = o + V((float)(System.Math.Cos(ang) * dist), (float)(rng.NextDouble() * 60 - 30), (float)(System.Math.Sin(ang) * dist));
                // 도달 가능 영역의 경계(안전 포물선): y <= v^2/(2g) - g x^2/(2 v^2). 경계에서 0.5 이내는 판정하지 않는다
                double dx = (double)t.X - o.X, dy = (double)t.Y - o.Y, dz = (double)t.Z - o.Z;
                double margin = (double)v * v / (2.0 * g) - g * (dx * dx + dz * dz) / (2.0 * v * v) - dy;
                if (System.Math.Abs(margin) < 0.5) continue;
                string e;
                if (margin > 0) { reach++; e = Both("무작위 #" + i, o, t, v, g); }
                else { unreachable++; e = Fail("무작위 #" + i, o, t, v, g); }
                if (e != null) return e;
            }
            return reach > 600 && unreachable > 600 ? null : "표본 부족: 도달 " + reach + " / 불가 " + unreachable;
        });
    }
}
